function onTheory(root){const w=root.querySelector('#w-gears');if(!w)return;
 let ring=true;
 w.innerHTML=`<b>Шестерёнки</b><label>Сколько шестерёнок: <input type="range" id="gn" min="3" max="12" value="7"><output id="gno"></output></label>
 <div style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0"><button class="btn" id="gring">По кругу</button><button class="btn ghost" id="gline">В ряд</button></div>
 <div id="gpic" class="fig" style="margin:6px 0"></div><div id="gout" style="font-size:16px;line-height:1.55"></div>`;
 const $=id=>w.querySelector('#'+id);
 const u=()=>{const n=+$('gn').value;$('gno').textContent=n;$('gpic').innerHTML=gears(n,ring,true);
  $('gring').className='btn'+(ring?'':' ghost');$('gline').className='btn'+(ring?' ghost':'');
  const last=n%2?'↻ (по часовой)':'↺ (против часовой)';
  $('gout').innerHTML=ring?(n%2?`${n}-я шестерёнка крутится ${last} — так же, как 1-я. А они соседки! <b style="color:var(--bad)">Заклинило ❌</b> — при нечётном числе по кругу механизм не работает.`:`${n}-я крутится ${last}, 1-я — ↻. Соседки крутятся в разные стороны — <b style="color:var(--ok)">всё работает ✅</b>.`)
   :`В ряд: нечётные номера ↻, чётные ↺. ${n}-я крутится ${last}. В цепочке механизм работает при любом числе шестерёнок ✅. Попробуй замкнуть в круг!`;};
 $('gn').oninput=u;$('gn').onchange=u;$('gring').onclick=()=>{ring=true;u();};$('gline').onclick=()=>{ring=false;u();};u();}

